async function login(e){e.preventDefault();if(!backend)return toast('Supabase não configurado. Atualize a página.');const f=new FormData(e.target),email=String(f.get('email')||'').trim().toLowerCase(),password=f.get('password');try{const credential=await backend.authSdk.signInWithEmailAndPassword(backend.auth,email,password),profileRef=backend.dataSdk.doc(backend.db,'users',credential.user.uid);let snap;try{snap=await backend.dataSdk.getDoc(profileRef)}catch(error){await backend.authSdk.signOut(backend.auth);throw Object.assign(error,{stage:'profile-read'})}if(!snap.exists()){await backend.authSdk.signOut(backend.auth);return toast(`Acesso autenticado, mas falta o perfil users/${credential.user.uid} no Supabase.`)}const profile=snap.data();if(profile.active!==true){await backend.authSdk.signOut(backend.auth);return toast('Usuário autenticado, porém o campo active do perfil não é boolean true.')}if(!profile.role){await backend.authSdk.signOut(backend.auth);return toast('Usuário autenticado, porém o perfil não possui o campo role.')}session={id:credential.user.uid,name:profile.fullName||credential.user.email,role:profile.role};await loadRemoteState();render()}catch(error){console.error('Falha no acesso',error);const code=String(error.code||'');if(error.stage==='profile-read'||code.includes('permission-denied'))toast('Authentication aceitou o usuário, mas o Supabase negou a leitura do perfil. Confira o UID e as regras.');else if(code.includes('invalid-credential')||code.includes('user-not-found')||code.includes('wrong-password'))toast('E-mail ou senha não conferem com o usuário cadastrado no Supabase Auth.');else if(code.includes('too-many-requests'))toast('Acesso temporariamente bloqueado após várias tentativas. Aguarde e tente novamente.');else toast('Falha no acesso: '+(error.message||code||'erro desconhecido'))}}
